const items = $input.all();

const juryPhones = {
  "Jury 1 - Immo": "+33600000001",
  "Jury 2 - Drone": "+33600000002",
  "Jury 3 - Immo": "+33600000003",
  "Jury 4 - Drone": "+33600000004",
  "Jury 5 - Drone": "+33600000005",
  "Jury 6 - Immo": "+33600000006",
  "Jury 7 - Drone": "+33600000007",
  "Jury 8 - Drone": "+33600000008",
