  "Jury 10 - Drone": "+33600000004",
  "Jury 11 - Immo": "+33600000009",
  "Jury 12 - Drone": "+33600000010",
  "Jury 13 - Drone": "+33600000011",
  "Jury 14 - Drone": "+33600000012",
  "Jury 15 - Drone": "+33600000013",
  "Jury 16 - Drone": "+33600000014",
