  "Jury 24 - Immo": "+33600000022",
  "Jury 25 - Drone": "+33600000023",
  "Jury 25 - Immo": "+33600000023",
  "Jury 26 - Immo": "+33600000024",
  "Jury 26 - Drone": "+33600000024",
  "Jury 27 - Drone": "+33600000025"
};

function normalizeJuryName(value) {
  if (!value) return "";

  return String(value)
    .normalize("NFC")
    .replace(/\u00A0/g, " ")
    .replace(/\s+/g, " ")
    .replace(/\s*-\s*/g, " - ")
    .trim();
}

const normalizedJuryPhones = {};

for (const [name, phone] of Object.entries(juryPhones)) {
  normalizedJuryPhones[normalizeJuryName(name)] = phone;
}

const seen = new Set();
const output = [];

for (const item of items) {
  const data = item.json.fields || item.json;

  const jurys = Array.isArray(data.Jurys)
    ? data.Jurys
    : data.Jurys
      ? [data.Jurys]
      : [];

  for (const rawJury of jurys) {
    const nomJury = normalizeJuryName(rawJury);
    const numero = normalizedJuryPhones[nomJury];

    if (!numero) continue;

    const key = numero;

    if (seen.has(key)) continue;
    seen.add(key);

    output.push({
      json: {
        jury_1_nom: nomJury.split(" - ")[0].trim(),
        jury_1_numero: numero
      }
    });
  }
}

return output;
